export const dict = { en, es }
export type T = Dict
export const money = (n: number) => '$' + n.toLocaleString('en-US')
export const rel = (iso: string, lang: 'en' | 'es') => {
  const s = (Date.now() - new Date(iso).getTime()) / 1000
  const f = new Intl.RelativeTimeFormat(lang, { numeric: 'auto' })
  if (s < 60) return f.format(-Math.round(s), 'second')
  if (s < 3600) return f.format(-Math.round(s / 60), 'minute')
  if (s < 86400) return f.format(-Math.round(s / 3600), 'hour')
  return f.format(-Math.round(s / 86400), 'day')
}
